#ifndef MODEL_REGISTRY_H_
#define MODEL_REGISTRY_H_

// Models compiled into the firmware (generated by training/export_firmware.py).

struct ModelEntry {
    const char* name;            // experiment name from training/run_experiments.py
    const char* description;
    const unsigned char* data;   // .tflite model (uint8 in/out)
    unsigned int size;           // bytes
};

extern const ModelEntry kModels[];
extern const int kModelCount;

// Own recordings ("<class>/<file>") the deployed models did not train on.
extern const char* const kOwnHeldOut[];
extern const int kOwnHeldOutCount;

#endif  // MODEL_REGISTRY_H_
